DATA = "/app/data"
OUT = "/app/output"
os.makedirs(OUT, exist_ok=True)

def parse_instance(path):
    with open(path) as f:
        toks = f.read().split()
    it = iter(toks)
    n_jobs = int(next(it)); n_mach = int(next(it))
    allowed = {}
    for j in range(n_jobs):
        n_ops = int(next(it))
        for o in range(n_ops):
            k = int(next(it))
            alts = {}
            for _ in range(k):
                m = int(next(it)); d = int(next(it))
                alts[m] = d
            allowed[(j, o)] = alts
    return n_jobs, n_mach, allowed

def parse_downtime(path):
    dt = {}
    with open(path) as f:
        r = csv.DictReader(f)
        for row in r:
            m = int(row["machine"])
            a = int(row["start"]); b = int(row["end"])
            dt.setdefault(m, []).append((a, b))
    for m in dt:
        dt[m].sort()
    return dt

def overlap(s, e, a, b):
    return s < b and a < e

def has_conflict(m, st, en, machine_intervals, downtime):
    for a, b in machine_intervals.get(m, []):
        if overlap(st, en, a, b):
            return True
    for a, b in downtime.get(m, []):
        if overlap(st, en, a, b):
            return True
    return False

def earliest_feasible(m, anchor, dur, machine_intervals, downtime, safety=500000):
    t = int(anchor)
    for _ in range(safety):
        if not has_conflict(m, t, t + dur, machine_intervals, downtime):
            return t
        t += 1
    return t

def main():
    n_jobs, n_mach, allowed = parse_instance(f"{DATA}/instance.txt")
    downtime = parse_downtime(f"{DATA}/downtime.csv")
    with open(f"{DATA}/policy.json") as f:
        policy = json.load(f)
    with open(f"{DATA}/baseline_solution.json") as f:
        baseline = json.load(f)

    base_makespan = baseline["makespan"]
    max_makespan = int(base_makespan * policy["guards"]["max_makespan_ratio"])
    max_mc = policy["change_budget"]["max_machine_changes"]
    max_shift = policy["change_budget"]["max_total_start_shift_L1"]
    freeze_enabled = policy["freeze"]["enabled"]
    freeze_until = policy["freeze"]["freeze_until"]

    base_list = baseline["schedule"]
    base_map = {(r["job"], r["op"]): r for r in base_list}
    base_index = {(r["job"], r["op"]): i for i, r in enumerate(base_list)}

    keys = list(base_map.keys())
    keys.sort(key=lambda k: (k[1], base_map[k]["start"], base_index[k]))

    machine_intervals = {}
    new_schedule = {}
    job_end = {}
    mc_used = 0
    shift_used = 0

    THRESH = 6

    for (j, o) in keys:
        br = base_map[(j, o)]
        base_m_orig = br["machine"]
        base_start = br["start"]

        alts = allowed[(j, o)]

        if freeze_enabled and base_start < freeze_until:
            m = base_m_orig
            st = base_start
            dur = br["end"] - br["start"]
            machine_intervals.setdefault(m, []).append((st, st + dur))
            new_schedule[(j, o)] = {"job": j, "op": o, "machine": m, "start": st, "end": st + dur, "dur": dur}
            job_end[j] = st + dur
            continue

        prev_end = job_end.get(j, 0)
        anchor = max(base_start, prev_end)

        base_m = base_m_orig if base_m_orig in alts else min(alts, key=lambda m: alts[m])

        def eval_machine(m):
            d = alts[m]
            st = earliest_feasible(m, anchor, d, machine_intervals, downtime)
            mc = int(m != base_m_orig)
            shift = abs(st - base_start)
            return (mc, shift, st, m, d)

        base_cand = eval_machine(base_m)

        best = base_cand
        # Consider alternates only if baseline yields large shift or would exceed budgets
        _, base_shift, base_st, _, _ = base_cand
        need_alt = (base_shift >= THRESH) or (shift_used + base_shift > max_shift)
        if need_alt:
            for m in alts:
                if m == base_m:
                    continue
                cand = eval_machine(m)
                cm, csh, cst, _, _ = cand
                if mc_used + cm > max_mc:
                    continue
                # lex: prefer lower (mc, shift, st)
                if (cm, csh, cst) < (best[0], best[1], best[2]):
                    best = cand

        mc, shift, st, m, d = best
        mc_used += mc
        shift_used += shift
        machine_intervals.setdefault(m, []).append((st, st + d))
        new_schedule[(j, o)] = {"job": j, "op": o, "machine": m, "start": st, "end": st + d, "dur": d}
        job_end[j] = st + d

    ordered = sorted(new_schedule.values(), key=lambda r: (r["start"], r["job"], r["op"]))
    makespan = max(r["end"] for r in ordered)

    # Validate
    print(f"Makespan: {makespan}  (baseline {base_makespan}, max {max_makespan})")
    print(f"Machine changes: {mc_used}/{max_mc}")
    print(f"Shift L1: {shift_used}/{max_shift}")

    # Check violations
    viol = 0
    for r in ordered:
        for a, b in downtime.get(r["machine"], []):
            if overlap(r["start"], r["end"], a, b):
                if freeze_enabled and r["start"] < freeze_until:
                    continue
                print(f"  DT VIOL: J{r['job']} op{r['op']} m{r['machine']} [{r['start']},{r['end']}] vs [{a},{b}]")
                viol += 1
    # Precedence
    for j in range(n_jobs):
        ops = sorted([r for r in ordered if r["job"] == j], key=lambda r: r["op"])
        for i in range(1, len(ops)):
            if ops[i]["start"] < ops[i - 1]["end"]:
                print(f"  PREC VIOL: J{j} op{i}")
                viol += 1
    # Machine overlaps
    by_m = {}
    for r in ordered:
        by_m.setdefault(r["machine"], []).append(r)
    for m, lst in by_m.items():
        lst.sort(key=lambda r: r["start"])
        for i in range(1, len(lst)):
            if lst[i]["start"] < lst[i - 1]["end"]:
                print(f"  MACHINE OVERLAP m{m}: {lst[i - 1]} vs {lst[i]}")
                viol += 1

    print(f"Violations: {viol}")

    status = "FEASIBLE" if (viol == 0 and makespan <= max_makespan and mc_used <= max_mc and shift_used <= max_shift) else "INFEASIBLE"

    solution = {"status": status, "makespan": makespan, "schedule": ordered}
    with open(f"{OUT}/solution.json", "w") as f:
        json.dump(solution, f, indent=2)

    with open(f"{OUT}/schedule.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["job", "op", "machine", "start", "end", "dur"])
        for r in ordered:
            w.writerow([r["job"], r["op"], r["machine"], r["start"], r["end"], r["dur"]])

    print("Wrote /app/output/solution.json and schedule.csv")

if __name__ == "__main__":
    main()
