{"command": "create", "path": "/app/repair_enum.py", "file_text": "import json, csv, os, itertools

DATA = "/app/data"
OUT = "/app/output"
os.makedirs(OUT, exist_ok=True)

def parse_instance(path):
    with open(path) as f:
        toks = f.read().split()
    it = iter(toks)
    n_jobs = int(next(it)); n_mach = int(next(it))
    allowed = {}
    for j in range(n_jobs):
        n_ops = int(next(it))
        for o in range(n_ops):
            k = int(next(it))
            alts = {}
            for _ in range(k):
                m = int(next(it)); d = int(next(it))
                alts[m] = d
            allowed[(j, o)] = alts
    return n_jobs, n_mach, allowed

def parse_downtime(path):
    dt = {}
    with open(path) as f:
        for row in csv.DictReader(f):
            dt.setdefault(int(row["machine"]), []).append((int(row["start"]), int(row["end"])))
    for m in dt: dt[m].sort()
    return dt

def overlap(s,e,a,b): return s<b and a<e

def has_conflict(m, st, en, machine_intervals, downtime):
    for a,b in machine_intervals.get(m, []):
        if overlap(st,en,a,b): return True
    for a,b in downtime.get(m, []):
        if overlap(st,en,a,b): return True
    return False

def earliest_feasible(m, anchor, dur, machine_intervals, downtime, safety=500000):
    t = int(anchor)
    for _ in range(safety):
        if not has_conflict(m, t, t+dur, machine_intervals, downtime):
            return t
        t += 1
    return t

def simulate(order, choice, base_map, allowed, downtime, freeze_enabled, freeze_until):
    machine_intervals = {}
    new_schedule = {}
    job_end = {}
    mc_used = 0
    shift_used = 0
    for k in order:
        j,o = k
        br = base_map[k]
        base_m_orig = br["machine"]; base_start = br["start"]
        if freeze_enabled and base_start < freeze_until:
            m = base_m_orig; st = base_start; dur = br["end"]-br["start"]
            machine_intervals.setdefault(m,[]).append((st, st+dur))
            new_schedule[k] = (j,o,m,st,st+dur,dur)
            job_end[j] = st+dur
            continue
        m = choice[k]
        d = allowed[k][m]
        prev_end = job_end.get(j, 0)
        anchor = max(base_start, prev_end)
        st = earliest_feasible(m, anchor, d, machine_intervals, downtime)
        machine_intervals.setdefault(m,[]).append((st, st+d))
        new_schedule[k] = (j,o,m,st,st+d,d)
        job_end[j] = st+d
        if m != base_m_orig: mc_used += 1
        shift_used += abs(st - base_start)
    makespan = max(r[4] for r in new_schedule.values())
    return makespan, mc_used, shift_used, new_schedule

def main():
    n_jobs, n_mach, allowed = parse_instance(f"{DATA}/instance.txt")
    downtime = parse_downtime(f"{DATA}/downtime.csv")
    with open(f"{DATA}/policy.json") as f: policy = json.load(f)
    with open(f"{DATA}/baseline_solution.json") as f: baseline = json.load(f)

    base_makespan = baseline["makespan"]
    max_makespan = int(base_makespan * policy["guards"]["max_makespan_ratio"])
    max_mc = policy["change_budget"]["max_machine_changes"]
    max_shift = policy["change_budget"]["max_total_start_shift_L1"]
    freeze_enabled = policy["freeze"]["enabled"]
    freeze_until = policy["freeze"]["freeze_until"]

    base_list = baseline["schedule"]
    base_map = {(r["job"], r["op"]): r for r in base_list}
    base_index = {(r["job"], r["op"]): i for i, r in enumerate(base_list)}
    keys = list(base_map.keys())
    keys.sort(key=lambda k: (k[1], base_map[k]["start"], base_index[k]))

    unfrozen = [k for k in keys if not (freeze_enabled and base_map[k]["start"] < freeze_until)]
    machine_opts = [list(allowed[k].keys()) for k in unfrozen]

    best = None
    for combo in itertools.product(*machine_opts):
        choice = {k: m for k, m in zip(unfrozen, combo)}
        ms, mc, sh, sched = simulate(keys, choice, base_map, allowed, downtime, freeze_enabled, freeze_until)
        if mc > max_mc or sh > max_shift or ms > max_makespan:
            continue
        # baseline had 36 makespan; also require not worse than baseline
        if ms > base_makespan:
            continue
        key = (ms, mc, sh)
        if best is None or key < best[0]:
            best = (key, sched, mc, sh, ms)

    if best is None:
        # fall back: minimize makespan among feasible w.r.t. budgets
        for combo in itertools.product(*machine_opts):
            choice = {k: m for k, m in zip(unfrozen, combo)}
            ms, mc, sh, sched = simulate(keys, choice, base_map, allowed, downtime, freeze_enabled, freeze_until)
            if mc > max_mc or sh > max_shift or ms > max_makespan:
                continue
            key = (ms, mc, sh)
            if best is None or key < best[0]:
                best = (key, sched, mc, sh, ms)

    assert best is not None, "no feasible schedule found"
    _, sched, mc, sh, ms = best
    print(f"Best makespan={ms} mc={mc} shift={sh} (baseline {base_makespan}, budgets mc<={max_mc} shift<={max_shift} max_ms<={max_makespan})")

    rows = []
    for k in keys:
        j,o,m,s,e,d = sched[k]
        rows.append({"job": j, "op": o, "machine": m, "start": s, "end": e, "dur": d})
    ordered = sorted(rows, key=lambda r: (r["start"], r["job"], r["op"]))

    solution = {"status": "FEASIBLE", "makespan": ms, "schedule": ordered}
    with open(f"{OUT}/solution.json", "w") as f:
        json.dump(solution, f, indent=2)
    with open(f"{OUT}/schedule.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["job","op","machine","start","end","dur"])
        for r in ordered:
            w.writerow([r["job"],r["op"],r["machine"],r["start"],r["end"],r["dur"]])
    print("Wrote solution.json and schedule.csv")

if __name__ == "__main__":
    main()
